async (page) => {
  const events = [];
  let cur = null;
  page.on('pageerror', e => events.push({sec: cur, type: 'pageerror', msg: e.message}));
  page.on('console', m => events.push({sec: cur, type: 'console-'+m.type(), msg: m.text()}));
  const buttons = await page.locator('button').all();
  const info = [];
  for (const b of buttons) {
    const txt = await b.innerText();
    const sec = await b.evaluate(el => { const s = el.closest('section,div,[id]'); return (s && (s.id || s.querySelector('h1,h2,h3,h4')?.textContent)) || ''; });
    cur = txt + ' | ' + sec;
    info.push(cur);
    await b.click();
    await page.waitForTimeout(1500);
  }
  return {info, events};
}

