async (page) => {
  await page.reload();
  await page.evaluate(() => {
    window.__ev = [];
    window.addEventListener('error', e => window.__ev.push({t:'exception', m:String(e.message), time: Date.now()}), true);
    window.addEventListener('unhandledrejection', e => window.__ev.push({t:'rejection', m:String(e.reason && e.reason.message || e.reason), time: Date.now()}));
  });
  const res = {};
  const buttons = await page.locator('button').all();
  const letters = 'ABCDEFGH';
  for (let i=0;i<buttons.length;i++) {
    await page.evaluate(() => window.__ev = []);
    await buttons[i].click();
    await page.waitForTimeout(4000);
    res[letters[i]] = await page.evaluate(() => window.__ev);
  }
  return res;
}

